
"use strict";

const CHAVE = "gerenciadorTarefas";
let tarefas = carregarTarefas();

const form = document.getElementById("formTarefa");
const campoTitulo = document.getElementById("titulo");
const campoPrioridade = document.getElementById("prioridade");
const busca = document.getElementById("buscaCodigo");
const filtro = document.getElementById("filtroStatus");
const lista = document.getElementById("listaTarefas");
const vazio = document.getElementById("vazio");
const mensagem = document.getElementById("mensagem");

function carregarTarefas() {
  try {
      const dados = JSON.parse(localStorage.getItem(CHAVE));
          return Array.isArray(dados) ? dados : [];
            } catch (erro) {
                return [];
                  }
                  }

                  function salvarTarefas() {
                    localStorage.setItem(CHAVE, JSON.stringify(tarefas));
                    }

                    function validarTarefa(titulo, prioridade) {
                      if (typeof titulo !== "string" ||
                            titulo.trim().length < 5) {
                                throw new Error(
                                      "O título precisa ter pelo menos 5 caracteres."
                                          );
                                            }

                                              const nivel = Number(prioridade);

                                                if (!Number.isInteger(nivel) || nivel < 1 || nivel > 3) {
                                                    throw new Error("A prioridade deve ser de 1 a 3.");
                                                      }

                                                        return {
                                                            titulo: titulo.trim(),
                                                                prioridade: nivel
                                                                  };
                                                                  }

                                                                  function gerarCodigo() {
                                                                    const maior = tarefas.reduce((numero, tarefa) => {
                                                                        const atual = Number(tarefa.codigo.replace("T-", "")) || 0;
                                                                            return Math.max(numero, atual);
                                                                              }, 0);

                                                                                return "T-" + String(maior + 1).padStart(3, "0");
                                                                                }

                                                                                function cadastrarTarefa(evento) {
                                                                                  evento.preventDefault();
                                                                                    mensagem.textContent = "";

                                                                                      try {
                                                                                          const dados = validarTarefa(
                                                                                                campoTitulo.value,
                                                                                                      campoPrioridade.value
                                                                                                          );

                                                                                                              const tarefa = {
                                                                                                                    codigo: gerarCodigo(),
                                                                                                                          titulo: dados.titulo,
                                                                                                                                prioridade: dados.prioridade,
                                                                                                                                      concluida: false,
                                                                                                                                            criadaEm: new Date().toISOString()
                                                                                                                                                };

                                                                                                                                                    tarefas.push(tarefa);
                                                                                                                                                        salvarTarefas();

                                                                                                                                                            form.reset();
                                                                                                                                                                campoPrioridade.value = "2";

                                                                                                                                                                    mensagem.textContent =
                                                                                                                                                                          "Tarefa " + tarefa.codigo + " cadastrada!";
                                                                                                                                                                              mensagem.style.color = "green";

                                                                                                                                                                                  renderizarTarefas();
                                                                                                                                                                                    } catch (erro) {
                                                                                                                                                                                        mensagem.textContent = erro.message;
                                                                                                                                                                                            mensagem.style.color = "red";
                                                                                                                                                                                              }
                                                                                                                                                                                              }

                                                                                                                                                                                              function buscarTarefa(codigo) {
                                                                                                                                                                                                return tarefas.find(tarefa =>
                                                                                                                                                                                                    tarefa.codigo.toLowerCase() === codigo.toLowerCase()
                                                                                                                                                                                                      );
                                                                                                                                                                                                      }

                                                                                                                                                                                                      function concluirTarefa(codigo) {
                                                                                                                                                                                                        const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                          if (!tarefa) return;

                                                                                                                                                                                                            tarefa.concluida = !tarefa.concluida;
                                                                                                                                                                                                              salvarTarefas();
                                                                                                                                                                                                                renderizarTarefas();
                                                                                                                                                                                                                }

                                                                                                                                                                                                                function alterarPrioridade(codigo) {
                                                                                                                                                                                                                  const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                    if (!tarefa) return;

                                                                                                                                                                                                                      tarefa.prioridade =
                                                                                                                                                                                                                          tarefa.prioridade === 3 ? 1 : tarefa.prioridade + 1;

                                                                                                                                                                                                                            salvarTarefas();
                                                                                                                                                                                                                              renderizarTarefas();
                                                                                                                                                                                                                              }

                                                                                                                                                                                                                              function nomePrioridade(nivel) {
                                                                                                                                                                                                                                if (nivel === 1) return "Baixa";
                                                                                                                                                                                                                                  if (nivel === 2) return "Média";
                                                                                                                                                                                                                                    return "Alta";
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    function renderizarTarefas() {
                                                                                                                                                                                                                                      const termo = busca.value.trim().toLowerCase();
                                                                                                                                                                                                                                        const status = filtro.value;

                                                                                                                                                                                                                                          const filtradas = tarefas.filter(tarefa => {
                                                                                                                                                                                                                                              const codigoCorresponde =
                                                                                                                                                                                                                                                    tarefa.codigo.toLowerCase().includes(termo);

                                                                                                                                                                                                                                                        const statusCorresponde =
                                                                                                                                                                                                                                                              status === "todas" ||
                                                                                                                                                                                                                                                                    (status === "pendente" && !tarefa.concluida) ||
                                                                                                                                                                                                                                                                          (status === "concluida" && tarefa.concluida);

                                                                                                                                                                                                                                                                              return codigoCorresponde && statusCorresponde;
                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                  filtradas.sort((a, b) =>
                                                                                                                                                                                                                                                                                      Number(a.concluida) - Number(b.concluida) ||
                                                                                                                                                                                                                                                                                          b.prioridade - a.prioridade
                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                              lista.replaceChildren();

                                                                                                                                                                                                                                                                                                filtradas.forEach(tarefa => {
                                                                                                                                                                                                                                                                                                    const item = document.createElement("div");
                                                                                                                                                                                                                                                                                                        item.className = "tarefa";

                                                                                                                                                                                                                                                                                                            if (tarefa.concluida) {
                                                                                                                                                                                                                                                                                                                  item.classList.add("concluida");
                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                          const checkbox = document.createElement("input");
                                                                                                                                                                                                                                                                                                                              checkbox.type = "checkbox";
                                                                                                                                                                                                                                                                                                                                  checkbox.checked = tarefa.concluida;
                                                                                                                                                                                                                                                                                                                                      checkbox.setAttribute(
                                                                                                                                                                                                                                                                                                                                            "aria-label",
                                                                                                                                                                                                                                                                                                                                                  "Concluir " + tarefa.titulo
                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                          checkbox.addEventListener("change", () =>
                                                                                                                                                                                                                                                                                                                                                                concluirTarefa(tarefa.codigo)
                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                        const conteudo = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                            conteudo.className = "tarefa-conteudo";

                                                                                                                                                                                                                                                                                                                                                                                const titulo = document.createElement("h3");
                                                                                                                                                                                                                                                                                                                                                                                    titulo.textContent = tarefa.titulo;

                                                                                                                                                                                                                                                                                                                                                                                        const detalhes = document.createElement("small");
                                                                                                                                                                                                                                                                                                                                                                                            detalhes.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                  tarefa.codigo + " • Prioridade " +
                                                                                                                                                                                                                                                                                                                                                                                                        nomePrioridade(tarefa.prioridade) + " • " +
                                                                                                                                                                                                                                                                                                                                                                                                              (tarefa.concluida ? "Concluída" : "Pendente");

                                                                                                                                                                                                                                                                                                                                                                                                                  detalhes.className =
                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa.prioridade === 3 ? "prioridade-alta" :
                                                                                                                                                                                                                                                                                                                                                                                                                              tarefa.prioridade === 2 ? "prioridade-media" :
                                                                                                                                                                                                                                                                                                                                                                                                                                    "prioridade-baixa";

                                                                                                                                                                                                                                                                                                                                                                                                                                        const data = document.createElement("small");
                                                                                                                                                                                                                                                                                                                                                                                                                                            data.textContent = " • " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                  new Date(tarefa.criadaEm).toLocaleDateString("pt-BR");

                                                                                                                                                                                                                                                                                                                                                                                                                                                      conteudo.append(titulo, detalhes, data);

                                                                                                                                                                                                                                                                                                                                                                                                                                                          const botao = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                              botao.type = "button";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  botao.textContent = "↑ Prioridade";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      botao.addEventListener("click", () =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alterarPrioridade(tarefa.codigo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item.append(checkbox, conteudo, botao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(item);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            vazio.style.display = filtradas.length ? "none" : "block";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const concluidas = tarefas.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tarefa => tarefa.concluida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById("totalTarefas").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          tarefas.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("totalConcluidas").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                concluidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById("totalPendentes").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tarefas.length - concluidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const percentual = tarefas.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? Math.round(concluidas / tarefas.length * 100)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById("progresso").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      percentual + "%";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function limparConcluidas() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefas = tarefas.filter(tarefa => !tarefa.concluida);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          salvarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            renderizarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mensagem.textContent = "Lista de concluídas atualizada.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagem.style.color = "green";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                form.addEventListener("submit", cadastrarTarefa);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                busca.addEventListener("input", renderizarTarefas);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                filtro.addEventListener("change", renderizarTarefas);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("limparConcluidas")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .addEventListener("click", limparConcluidas);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  renderizarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  